const listeners = [];
function on(fn) { listeners.push(fn); }
function off(fn) {
  const i = listeners.indexOf(fn);
  if (i >= 0) listeners.splice(i, 1);
}
function emit(msg) {
  for (const fn of listeners.slice()) fn(msg);
}

public sealed class RabbitPipeline
{
    private readonly List<Func<RabbitMessage, CancellationToken, Task>> _steps = [];

    public void Use(Func<RabbitMessage, CancellationToken, Task> step) => _steps.Add(step);

    public async Task RunAsync(RabbitMessage message, CancellationToken ct)
    {
        foreach (var step in _steps)
            await step(message, ct);
    }
}

